      const dashboardLatencyPoints=adminDashboardSamples.map(sample=>`${Math.max(0,700-((Date.now()-sample.at)/3600000)*700).toFixed(1)},${(82-(sample.ms/dashboardLatencyMax)*66).toFixed(1)}`);
